using System;
using TNS.Veri;
using TNS;


namespace TNS.BKD.IsKurallari.Veri
{
    /// <summary>
    /// Bütçe kodlarının tutulduğu farklı tablolara erişim sağlayan yordamları ve erişim bilgilerini tutan sınıf.
    /// </summary>
    public class TABButceKod : TABOrtak
    {
        /// <summary>
        /// Sql kosul kısımında yıl alanı değeri olarak kullanılır.
        /// </summary>
        int yil;

        /// <summary>
        /// İşlem yapılacak kodun tür kodu (Değişken.xml'den kodların adları ve numaraları bulunabilir.)
        /// </summary>
        int kodTuru;

        /// <summary>
        /// İşlem yapılacak kodun adı. (Degisken.xml'deki kod no yada kd adı verilmelidir.)
        /// </summary>
        string kodAd;

        /// <summary>
        /// İşlem yapılacak kodun kırılım yapısı.
        /// </summary>
        string kodYapi;

        /// <summary>
        /// İşlem yapılacak kodun veri tabanındaki tablo ismi.
        /// </summary>
        string tabloAd;

        /// <summary>
        /// İşlem yapılacak kodun veri tabanındaki tablodaki kod kolonunun ismi.
        /// </summary>
        string vtAlanKod;

        /// <summary>
        /// İşlem yapılacak kodun veri tabanındaki tablodaki ad kolonunun ismi. Bu alana dil için ek yapılarak dil alanlarının ismi bulunur.
        /// </summary>
        string vtAlanAd;

        bool yilYok;

        /// <summary>
        /// Bütçe kodlarının tutulduğu farklı tablolara erişim sağlayan, erişim bilgilerini alarak yeni bir tablo nesnesi oluşturan oluşturucu yordam.
        /// </summary>
        /// <param name="veriErisim">Tablonun bulunduğu veri tabanına erişim sağlayan veri erişim nesnesi.</param>
        /// <param name="yil">Sql kosul kısımında yıl alanı değeri olarak kullanılır.</param>
        /// <param name="kodTuru">İşlem yapılacak kodun tür kodu (Değişken.xml'den kodların adları ve numaraları bulunabilir.)</param>
        /// <param name="kodAd">İşlem yapılacak kodun adı. (Degisken.xml'deki kod no yada kd adı verilmelidir.)</param>
        /// <param name="kodYapi">İşlem yapılacak kodun kırılım yapısı.</param>
        /// <param name="tabloAd">İşlem yapılacak kodun veri tabanındaki tablo ismi.</param>
        /// <param name="vtAlanKod">İşlem yapılacak kodun veri tabanındaki tablodaki kod kolonunun ismi.</param>
        /// <param name="vtAlanAd">İşlem yapılacak kodun veri tabanındaki tablodaki ad kolonunun ismi. Bu alana dil için ek yapılarak dil alanlarının ismi bulunur.</param>
        public TABButceKod(VeriErisim veriErisim, int yil, int kodTuru, string kodAd, string kodYapi, string tabloAd, string vtAlanKod, string vtAlanAd, bool yilYok)
            : base(veriErisim)
        {
            this.yil = yil;
            this.kodTuru = kodTuru;
            this.kodAd = kodAd;
            this.kodYapi = kodYapi;
            this.tabloAd = tabloAd;
            this.vtAlanKod = vtAlanKod;
            this.vtAlanAd = vtAlanAd;
            this.yilYok = yilYok;
        }

        // Verilen kod varsa güncellenir, yoksa eklenir

        /// <summary>
        /// Verilen kodun farklı dillerdeki adını veri tabanında güncelleyen, güncelleme olmazsa ekleyen yordam.
        /// Tüm diller için dil adından alan adı bulunur ve alan adı ve değeri kullanılarak güncelleme komutu üretilir. (alanadı=değer)
        /// Eğer güncelleme başarısız olursa, alandı ekleme komutu alan listesinde, değeri ise değer listesine eklenir ve ekleme komutu çalıştırılır.
        /// </summary>
        /// <param name="kod">Güncellenecek yada eklenecek kodun değeri.</param>
        /// <param name="yabanciAdlar">Farklı dillerde adlar bu değikende tutulur. Hash table yapısının anahtarı dil kodu, değeri ise adı ve açıklamayı tutan ABSKodDil yapısında nesnedir.</param>
        /// <returns>Verilen bilgilerle elde edilen güncelleme komutu, güncelleme başarısız ise ekleme komutunun çalıştırılmasının sonucunu, Sonuc yapısında döndürür.</returns>
        public Sonuc EkleVeyaGuncelle(string kod, DilTable yabanciAdlar, EkAlanDeger[] ekAlanlar)
        {
            kod = kod.Replace(".", "");
            string sql = string.Empty;
            for (int i = 0; i < yabanciAdlar.Length; i++)
            {
                if (!string.IsNullOrEmpty(yabanciAdlar.dilKod[i]))
                {
                    string alanAd = vtAlanAd + Arac.AlanEkBul(yabanciAdlar.dilKod[i]);
                    ABSKodDil kd = yabanciAdlar.absKodDil[i];
                    if (sql != string.Empty) sql += ", ";
                    sql = sql + VeriErisim.AtamaOl("", alanAd, (string)kd.ad);
                }
            }
            if (ekAlanlar != null)
            {
                foreach (EkAlanDeger ekAlanDeger in ekAlanlar)
                {
                    if (!string.IsNullOrEmpty(sql)) sql += ", ";
                    if (ekAlanDeger.ekAlan.enumMaske == ENUMMaskeEkAlan.Number)
                        sql = sql + VeriErisim.AtamaOl("", ekAlanDeger.ekAlan.ad, OrtakFonksiyonlar.ConvertToInt(ekAlanDeger.Deger, 0));//(int)ekAlanDeger.Deger);
                    else if (ekAlanDeger.ekAlan.enumMaske == ENUMMaskeEkAlan.TNSDateTime)
                        sql = sql + VeriErisim.AtamaOl("", ekAlanDeger.ekAlan.ad, (TNSDateTime)ekAlanDeger.Deger);
                    else //if (ekAlanDeger.ekAlan.enumMaske == ENUMMaskeEkAlan.String)
                        sql = sql + VeriErisim.AtamaOl("", ekAlanDeger.ekAlan.ad, OrtakFonksiyonlar.ConvertToStr(ekAlanDeger.Deger));//(string)ekAlanDeger.Deger);
                }
            }

            sql = "UPDATE " + tabloAd + " SET " + sql + " WHERE ";
            if (!yilYok)
            {
                sql = sql + VeriErisim.KosulOl("", "YIL", "=", yil);
                sql = sql + " AND ";
            }
            sql = sql + VeriErisim.KosulOl("", vtAlanKod, "=", kod);

            Sonuc sonuc = KomutCalistir(sql, 1);

            if (sonuc.hataStr != string.Empty)
            {
                string sql2 = "INSERT INTO " + tabloAd + "(";
                if (!yilYok)
                    sql2 += "YIL, ";
                sql2 += vtAlanKod;

                for (int i = 0; i < yabanciAdlar.Length; i++)
                {
                    if (!string.IsNullOrEmpty(yabanciAdlar.dilKod[i]))
                    {
                        string yabanciAlanAd = vtAlanAd + Arac.AlanEkBul(yabanciAdlar.dilKod[i]);
                        sql2 += ", " + yabanciAlanAd;
                    }
                }

                if (ekAlanlar != null)
                {
                    foreach (EkAlanDeger ekAlan in ekAlanlar)
                        sql2 += ", " + ekAlan.ekAlan.ad;
                }

                sql2 += ") VALUES (";
                if (!yilYok)
                    sql2 = sql2 + VeriErisim.DegerYap(yil) + ", ";
                sql2 = sql2 + VeriErisim.DegerYap(kod);

                for (int i = 0; i < yabanciAdlar.Length; i++)
                {
                    if (!string.IsNullOrEmpty(yabanciAdlar.dilKod[i]))
                    {
                        ABSKodDil kd = (ABSKodDil)yabanciAdlar.absKodDil[i];
                        sql2 += ", " + VeriErisim.DegerYap(kd.ad);
                    }
                }


                if (ekAlanlar != null)
                {
                    foreach (EkAlanDeger ekAlan in ekAlanlar)
                    {
                        if (ekAlan.ekAlan.enumMaske == ENUMMaskeEkAlan.Number)
                            sql2 += ", " + VeriErisim.DegerYap(OrtakFonksiyonlar.ConvertToInt(ekAlan.Deger, 0));
                        else if (ekAlan.ekAlan.enumMaske == ENUMMaskeEkAlan.TNSDateTime)
                            sql2 += ", " + VeriErisim.DegerYap((TNSDateTime)ekAlan.Deger);
                        else //if (ekAlan.ekAlan.enumMaske == ENUMMaskeEkAlan.String)
                            sql2 += ", " + VeriErisim.DegerYap(OrtakFonksiyonlar.ConvertToStr(ekAlan.Deger));
                    }
                }
                sql2 = sql2 + ")";
                sonuc = KomutCalistir(sql2, 1);
            }
            return sonuc;
        }

        // Verilen yılda, koda ait altkod var mı diye bakılır.

        /// <summary>
        /// Verilen kod silinmeden önce, kod hiyerarşisinde, kendisine bağlı alt kodlar var mı diye bakan yordam.
        /// Bulanan kayıt sayısı Sonuc yapısının kayıt sayısı alanında, kayıt sayısı 0 ise sonu yapısı yanlış, sıfırdan büyük ise doğru döndürülür.
        /// </summary>
        /// <param name="kod">Hiyerarşik olarak kendisine bağlı alt kodlar var mı diye kontrol edilecek kod.</param>
        /// <returns>Sonuç yapısında kayıt sayısı ve işlem sonuc alanlarında bilgi döndürülür.</returns>
        public Sonuc VeriVarMi(string kod)
        {
            Sonuc sonuc = new Sonuc(false, "", "");
            sonuc.kayitSay = -1;
            string sql = "SELECT COUNT(" + vtAlanKod + ") FROM " + tabloAd + " WHERE ";
            if (!yilYok)
            {
                sql = sql + VeriErisim.KosulOl("", "YIL", "=", yil);
                sql = sql + " AND ";
            }
            sql = sql + VeriErisim.KosulOl("", vtAlanKod, " LIKE ", kod + VeriErisim.IslecBul("%", veriErisim.baglantiAd));
            sql = sql + " AND " + VeriErisim.KosulOl("", VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ")", ">", kod.Length);
            System.Data.IDataReader r = veriErisim.DataReaderDondur(sql);
            if (veriErisim.hata == "")
            {
                if (r.Read())
                {
                    sonuc.kayitSay = VeriErisim.DegerAl(r, 0, 0);
                    if (sonuc.kayitSay == 0)
                        sonuc.islemSonuc = false;
                    else
                        sonuc.islemSonuc = true;
                }
                else
                    sonuc.islemSonuc = true;

                r.Close();
            }
            else
            {
                sonuc.hataStr = veriErisim.hata;
                sonuc.islemSonuc = true;
            }
            return sonuc;
        }

        //* verilen kod bilgilerini siler
        /// <summary>
        /// Verilen kodun, ilgili yıldaki tanım bilgisini veri tabanından silen yordam.
        /// </summary>
        /// <param name="kod">Silinecek kodun değeri.</param>
        /// <returns>Oluşturulan delete komutunun çalıştırılmasının sonucunu, Sonuc yapısında döndürür.</returns>
        public Sonuc KodSil(string kod)
        {
            string sql = "DELETE FROM " + tabloAd + " WHERE ";

            if (!yilYok)
            {
                sql = sql + VeriErisim.KosulOl("", "YIL", "=", yil);
                sql = sql + " AND ";
            }
            sql = sql + VeriErisim.KosulOl("", vtAlanKod, "=", kod);
            return KomutCalistir(sql, 0);
        }

        /// <summary>
        /// Verilen sql koşul cümleciği; kodları, adları ile listeleyen select cümlesine ekleyen ve oluşturulan Select cümlesini çalıştırıp, sonucunu döndüren yordam.
        /// Ad alanları select listesine, diller dizisine göre eklenir.
        /// </summary>
        /// <param name="kosul">Select cümlesine eklenecek kosul cümlesi.</param>
        /// <returns>Oluşturulan select cümlesinin sonucu DataReader olarak döndürülür.</returns>
        private System.Data.IDataReader ListeleKosul(string kosul, EkAlan[] ekAlanlar, bool distinct, bool adaGoreSirala)
        {
            string sql = "SELECT ";
            if (distinct)
                sql += "DISTINCT ";
            sql += vtAlanKod;

            for (int i = 0; i < TNS.BKD.Arac.DillerLength; i++)
            {
                string yabanciAlanAd = vtAlanAd + Arac.AlanEkBul(i);
                sql += ", " + yabanciAlanAd;
            }
            if (ekAlanlar != null)
            {
                foreach (EkAlan ekAlan in ekAlanlar)
                    sql += ", " + ekAlan.ad;
            }
            sql = sql + " FROM " + tabloAd;
            if (kosul != "")
            {
                if (!kosul.Contains("where"))
                    sql = sql + " Where ";
                sql = sql + kosul;
            }

            if (!sql.Contains("order by"))
            {
                if (adaGoreSirala)
                    sql += " ORDER BY " + vtAlanAd;
                else
                    sql += " ORDER BY " + vtAlanKod + "," + vtAlanAd;
            }

            return veriErisim.DataReaderDondur(sql);
        }

        /// <summary>
        /// Verilen kod dizgisi ile başlayan ve
        ///     - seviye 0 ise kodun bir alt kırılımındaki kodları
        ///     - seviye 0 değilse, 
        ///         - sadeceDetay ise verilen seviyedeki kodları
        ///         - sadeceDetay değil ise, kod ile seviye arasındaki tüm kodları
        /// listeleyen sql koşulunu oluşturup, ListeleKosul yordamını çağıran yordam.
        /// </summary>
        /// <param name="kod">Sonuç kümesindeki kodların benzer olacağı kod.</param>
        /// <param name="seviye"></param>
        /// <param name="sadeceDetay"></param>
        /// <returns>Verilen kriterlere göre oluşturulan select cümlesinin sonucu DataReader olarak döndürülür.</returns>
        public System.Data.IDataReader Listele(string kod, int seviye, bool sadeceDetay, EkAlan[] ekAlanlar, bool ikiYil, bool adaGoreSirala, string filtreKod, string baslangicFiltreKodAd)
        {
            string kosul = "";
            int kodLn;
            kod = OrtakFonksiyonlar.KodNoktaKoy(kodYapi, kod.Replace(".", ""));
            kodLn = kod.Length;

            if (!yilYok && yil > 0)
            {
                if (ikiYil)
                {
                    kosul = VeriErisim.KosulEkle(kosul, "AND", "(" + VeriErisim.KosulOl(tabloAd, "YIL", "=", yil) + " OR " + VeriErisim.KosulOl(tabloAd, "YIL", "=", yil + 1) + ")");
                }
                else
                    kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, "YIL", "=", yil));
            }
            if (!string.IsNullOrWhiteSpace(kod))
            {
                kod = kod.Replace(".", "");
                kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, vtAlanKod, " LIKE ", kod + VeriErisim.IslecBul("%")));
            }
            if (!string.IsNullOrWhiteSpace(filtreKod))
            {
                string icKosul = "";

                string[] filtreKodlar = filtreKod.Split(',', ';');
                for (int i = 0; i < filtreKodlar.Length; i++)
                {
                    icKosul = VeriErisim.KosulEkle(icKosul, "OR", VeriErisim.KosulOl(tabloAd, vtAlanKod, " LIKE ", filtreKodlar[i].Replace(".", "") + VeriErisim.IslecBul("%")));
                }
                if (!string.IsNullOrWhiteSpace(icKosul))
                    kosul = VeriErisim.KosulEkle(kosul, "AND", "(" + icKosul + ")");
            }
            if (!string.IsNullOrWhiteSpace(baslangicFiltreKodAd))
            {
                //seviye = -1;
                string[] kelimeler = baslangicFiltreKodAd.Split(' ');
                for (int i = 0; i < kelimeler.Length; i++)
                {
                    kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl("", tabloAd + "." + vtAlanKod + "+ ' ' +" + tabloAd + "." + vtAlanAd, " LIKE ", VeriErisim.IslecBul("%") + kelimeler[i] + VeriErisim.IslecBul("%")));
                }
            }
            if (kodYapi != "S" && kodYapi != "N")
            {
                if (seviye == 0)
                {
                    if (kodLn + 1 < kodYapi.Length)
                    {
                        int ln = kodYapi.IndexOf(".", kodLn + 1);
                        if (ln <= 0)
                            ln = kodYapi.Length;

                        string kodyapi = kodYapi.Substring(0, ln);
                        ln = kodyapi.Replace(".", "").Length;

                        kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ")=" + ln);
                    }
                }
                else if (seviye > 0)
                {
                    int karSay = -1;
                    for (int i = 0; i < seviye; i++)
                        karSay = kodYapi.IndexOf('.', karSay + 1);
                    if (karSay == -1)
                        karSay = kodYapi.Length;
                    string islec;
                    if (sadeceDetay)
                        islec = "=";
                    else
                        islec = "<=";

                    kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ")" + islec + (kodYapi.Substring(0, karSay).Replace(".", "")).Length);
                }
            }

            System.Data.IDataReader dr = ListeleKosul(kosul, ekAlanlar, ikiYil, adaGoreSirala);

            return dr;
        }

        /// <summary>
        /// Verilen kodun ilgili dildeki açıklamasını çekecek sql cümlesini üretip, datareader döndüren fonksiyon.
        /// </summary>
        /// <param name="kod">Sonuç kümesindeki kodların benzer olacağı kod.</param>
        /// <returns>Verilen kriterlere göre oluşturulan select cümlesinin sonucu DataReader olarak döndürülür.</returns>
        public System.Data.IDataReader Oku(string kod)
        {
            string kosul = "";

            if (!yilYok && yil > 0)
            {
                kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, "YIL", "=", yil));
            }
            kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, vtAlanKod, "=", kod.Replace(".", "")));

            string sql = "SELECT " + vtAlanAd + Arac.AlanEkBul() + " FROM " + tabloAd + " WHERE " + kosul;

            return veriErisim.DataReaderDondur(sql);
        }

        /// <summary>
        /// Verilen arama kıstası kullanılarak, kodlar aranır ve sonuç döndürülür. Arama kıstası boşluklardan bölünür. İlk kelime eğer sayı ile başlıyorsa kod için kullanılır değilse diğer tüm kelimelerle birlikte ad için kullanılır. Her ad ayrı ayrı sql koşuluna eklenir.
        /// Dil kodu kullanılarak hangi alanın döndürüleceği ve hangi alana sorgu uygulanacağı belirlenir.
        /// Oluşturulan sql çalıştırılır ve sonucu DateReader olarak döndürülür.
        /// </summary>
        /// <param name="dilKod">Adların aranacağı ve listeleneceği dil.</param>
        /// <param name="yil">Kodların listeleneceği yıl.</param>
        /// <param name="aramaKistas">Listelenecek kodların uyacağı arama dizgisi. Arama dizgisi boşluklardan bölünür. İlk parça hem kod için hem de ad için kullanılabilir. Diğer parçalar sadece ad için arama da kullanılır.</param>
        /// <returns>Verilen kriterlere uyan kodların listelendiği DataReader döndürülür.</returns>
        public System.Data.IDataReader Ara(string dilKod, int yil, string aramaKistas, EkAlan[] ekAlanlar, bool adaGoreSirala)
        {
            string adEk = "";
            string alanAd = vtAlanAd + adEk;
            string sql = "SELECT " + vtAlanKod + ", " + alanAd;
            if (ekAlanlar != null)
            {
                foreach (EkAlan ekAlan in ekAlanlar)
                    sql += ", " + ekAlan.ad;
            }
            sql += " FROM " + tabloAd;

            sql = VeriErisim.KosulEkle(sql, "WHERE", VeriErisim.KosulOl(tabloAd, "YIL", "=", yil));
            char[] ayraclar = { ' ' };
            string[] aramaParcalar = aramaKistas.Split(ayraclar, StringSplitOptions.RemoveEmptyEntries);
            if (aramaParcalar.Length == 0) return null;

            int kodBasla = 0;
            if (TNS.BKD.Arac.KodMu(aramaParcalar[0]))
            {
                sql = VeriErisim.KosulEkle(sql, "AND", VeriErisim.KosulOl(tabloAd, vtAlanKod, "LIKE", aramaParcalar[0].Replace(".", "") + "%"));
                kodBasla = 1;
            }
            for (int i = kodBasla; i < aramaParcalar.Length; i++)
            {
                sql = VeriErisim.KosulEkle(sql, "AND", "(" +
                    VeriErisim.KosulOl(tabloAd, alanAd, "LIKE", aramaParcalar[i] + "%")
                    + " OR " +
                    VeriErisim.KosulOl(tabloAd, alanAd, "LIKE", "% " + aramaParcalar[i] + "%")
                    + ")"
                    );
            }
            if (adaGoreSirala)
                sql += " ORDER BY " + vtAlanAd;
            else
                sql += " ORDER BY " + vtAlanKod;

            return this.veriErisim.DataReaderDondur(sql);
        }

        public int KayitSayiBul(int yil)
        {
            string kosul = "";

            if (!yilYok && yil > 0)
                kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, "YIL", "=", yil));

            string sql = "SELECT  COUNT(*) FROM " + tabloAd;

            if (kosul != "")
            {
                sql = sql + " Where " + kosul;
            }

            return veriErisim.TekKolonSQLInt(sql);
        }

        public double FiltreliKayitSay(string kod, string filtre)
        {
            string kosul = "";

            if (!yilYok && yil > 0)
            {
                kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, "YIL", "=", yil));
            }
            kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, vtAlanKod, "LIKE", kod.Replace(".", "") + "%"));
            kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl(tabloAd, vtAlanAd + Arac.AlanEkBul(), "LIKE", "%" + filtre + "%"));

            string sql = "SELECT COUNT(*) FROM " + tabloAd + " WHERE " + kosul;

            return veriErisim.TekKolonSQLDbl(sql);
        }


        /// <summary>
        /// Kurum listesi, 
        /// a) 30'dan küçükler için iki basamaklı kodlar veya
        /// b) 30'dan küçükler için, 3. ve 4. basamağı BHMaButceKodYapi.BagimsizKurumBaslangic()'den büyük 4 basamaklılar veya
        /// c) 30'dan büyük 4 basamaklılar
        /// 
        /// koşullarından oluşmaktadır.
        /// 
        /// Bu koşula yıl ve gelen ek koşul eklenerek kod ve ad yapısında sonuç datareader olarak döndürülür.
        /// </summary>
        /// <param name="ekKosul"></param>
        /// <param name="gelirlilerMi"></param>
        /// <returns></returns>
        public System.Data.IDataReader KurumListesiKosul(string ekKosul, bool kurkod4Bolum)
        {
            string kosul;
            if (kurkod4Bolum)
            {
                kosul = "((" + vtAlanKod + ">='" + TNS.BKD.Arac.DigerKurumlarBasla() + "' AND " + VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ") = 4" + ") OR ";
                kosul += "(" + vtAlanKod + ">'" + TNS.BKD.Arac.BelediyeBasla() + "' AND " + vtAlanKod + " <'" + TNS.BKD.Arac.BelediyeBit() + "' AND " + VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ") = 6" + ") OR ";
                kosul += "(" + vtAlanKod + ">'" + TNS.BKD.Arac.GenelButceSonKod() + "' AND " + vtAlanKod + " <'" + TNS.BKD.Arac.BelediyeBasla() + "' AND " + VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ") = 4" + ") OR ";
                kosul += "(" + vtAlanKod + "<'" + TNS.BKD.Arac.GenelButceSonKod() + "' AND " + VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ") = 2" + ") OR ";
                kosul += "(" + vtAlanKod + "<'" + TNS.BKD.Arac.GenelButceSonKod() + "' AND " + VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ") = 4 AND " + VeriErisim.IslecBul("SUBSTRING") + "(" + vtAlanKod + ", 3, 4) >= '" + TNS.BKD.Arac.BagimsizKurumBaslangic() + "'))";
            }
            else
                kosul = "(" + VeriErisim.IslecBul("LEN") + "(" + vtAlanKod + ") = 4" + ")";

            kosul = VeriErisim.KosulEkle(kosul, "AND", VeriErisim.KosulOl("", "YIL", "=", yil));
            if (ekKosul != "")
                kosul = VeriErisim.KosulEkle(kosul, "AND", ekKosul);

            return ListeleKosul(" where " + kosul + " order by " + vtAlanKod, null, true, false);
        }

